insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_mas_v1'
from (values
('113.50.c.1',3,'A student places the Spanish conquest of the Aztecs (1521), the Grito de Dolores (1810) and the Treaty of Guadalupe Hidalgo (1848) in order. What skill is being used?','["Applying chronology by sequencing events", "Reading a map scale", "Calculating a median", "Comparing primary sources"]'::jsonb,0,'Sequencing places events in order of time.','original'),
('113.50.c.1',3,'Which list places events in correct chronological order?','["Mexican-American War, Texas independence, Mexican independence", "Mexican independence (1821), Texas independence (1836), Mexican-American War (1846)", "Texas independence, Mexican independence, Mexican-American War", "Mexican independence, Mexican-American War, Texas independence"]'::jsonb,1,'Relative chronology compares which came first.','original'),
('113.50.c.2.A',3,'The Spanish conquest of the Aztec Empire is generally dated to the fall of Tenochtitlan in which year?','["1492", "1610", "1521", "1810"]'::jsonb,2,'Cortés and his allies took Tenochtitlan in 1521.','original'),
('113.50.c.2.A',3,'The New Laws of 1542 were significant because they did what?','["Created the Border Patrol", "Granted Mexico independence", "Ended Spanish rule", "Aimed to limit the enslavement and abuse of Indigenous people in Spanish colonies"]'::jsonb,3,'They responded to reformers such as Las Casas.','original'),
('113.50.c.2.B',3,'Bartolomé de las Casas is remembered for doing what?','["Defending the rights of Indigenous people against abuse by colonists", "Founding the Mexican Republic", "Leading the Aztec army", "Writing the Texas constitution"]'::jsonb,0,'He was a priest who spoke out against colonial violence.','original'),
('113.50.c.2.B',3,'Sor Juana Inés de la Cruz was a Spanish colonial-era figure known as what?','["An Aztec emperor", "A nun, poet and scholar who defended women''s right to education", "A conquistador", "A Revolution general"]'::jsonb,1,'She is one of the great writers of colonial Mexico.','original'),
('113.50.c.3.A',3,'The Grito de Dolores in 1810 was significant because it did what?','["Sold land to the United States", "Created the Border Patrol", "Began Mexico''s war for independence from Spain", "Ended the Mexican Revolution"]'::jsonb,2,'Father Miguel Hidalgo called for revolt.','original'),
('113.50.c.3.A',3,'The Treaty of Guadalupe Hidalgo (1848) did what?','["Began the Mexican Revolution", "Created the Bracero Program", "Declared Texas independent", "Ended the Mexican-American War and transferred much of present-day Southwest to the United States"]'::jsonb,3,'Mexicans living there could become U.S. citizens.','original'),
('113.50.c.3.B',3,'Emiliano Zapata is best known for doing what during the Mexican Revolution?','["Leading peasants in a fight for land reform", "Writing the Texas Declaration", "Founding LULAC", "Serving as Spain''s viceroy"]'::jsonb,0,'His slogan was land and liberty.','original'),
('113.50.c.3.B',3,'Francisco I. Madero became important in the Mexican Revolution because he did what?','["Founded the UFW", "Challenged Porfirio Díaz and was elected president in 1911", "Signed the New Laws", "Led the Spanish army"]'::jsonb,1,'His call for revolt began the Revolution.','original'),
('113.50.c.4.A',3,'The Bracero Program, begun in 1942, was a program that did what?','["Ended segregation", "Created La Raza Unida", "Brought Mexican workers to the United States for temporary agricultural labor", "Gave land to farmers"]'::jsonb,2,'It addressed wartime labor shortages.','original'),
('113.50.c.4.A',3,'In Hernández v. Texas (1954), the Supreme Court ruled that what?','["Segregated schools were legal", "Braceros could not work", "Texas could ban Spanish", "Mexican Americans were protected by the Fourteenth Amendment and could not be excluded from juries"]'::jsonb,3,'The Court recognized discrimination against a class other than Black and white.','original'),
('113.50.c.4.B',3,'César Chávez and Dolores Huerta are known for doing what?','["Organizing farmworkers through the United Farm Workers", "Writing the New Laws", "Founding the Border Patrol", "Leading the Mexican Revolution"]'::jsonb,0,'They led strikes and boycotts for better wages.','original'),
('113.50.c.4.B',3,'Héctor P. García is remembered for doing what?','["Leading the Aztec Empire", "Founding the American G.I. Forum to fight discrimination against Mexican American veterans", "Serving as mayor of San Antonio", "Winning the Nobel Prize in Chemistry"]'::jsonb,1,'The Longoria Affair brought the Forum national attention.','original'),
('113.50.c.5.A',3,'The Immigration Reform and Control Act of 1986 did what?','["Ended all immigration", "Created the Bracero Program", "Offered legal status to some undocumented immigrants while penalizing employers who hired unauthorized workers", "Abolished the Border Patrol"]'::jsonb,2,'It combined amnesty with enforcement.','original'),
('113.50.c.5.A',3,'H.R. 4437, passed by the House in 2006, led to what?','["The end of the Border Patrol", "The New Laws", "A national holiday", "Large nationwide protests against proposed harsher immigration penalties"]'::jsonb,3,'It would have increased penalties for unlawful presence.','original'),
('113.50.c.5.B ',3,'Willie Velásquez is known for founding what?','["The Southwest Voter Registration Education Project", "The Border Patrol", "The United Farm Workers", "The Aztec calendar"]'::jsonb,0,'His group registered many Latino voters.','original'),
('113.50.c.5.B ',3,'Henry Cisneros served as which of the following?','["Governor of Texas", "Mayor of San Antonio and a U.S. Secretary of Housing and Urban Development", "President of Mexico", "A Revolution general"]'::jsonb,1,'He was among the first Mexican American mayors of a major city.','original'),
('113.50.c.6.A',3,'The U.S.-Mexico border region is historically significant to Mexican American history because it does what?','["Has never been crossed", "Was created in 2006", "Is where cultures, families, trade and migration have long overlapped", "Is uninhabited"]'::jsonb,2,'The border was drawn after the Mexican-American War.','original'),
('113.50.c.6.A',3,'Tenochtitlan, site of present-day Mexico City, was the capital of which civilization?','["The Republic of Texas", "The Comanche", "The Spanish Empire", "The Aztec Empire"]'::jsonb,3,'It was built on an island in Lake Texcoco.','original'),
('113.50.c.6.B',3,'Which physical feature supported large settlements in the Valley of Mexico?','["Lakes and fertile land that supported agriculture", "Open ocean only", "Desert sand dunes only", "Polar ice"]'::jsonb,0,'Chinampas farms used lake shallows.','original'),
('113.50.c.6.B',3,'Why did many American Indian societies settle near rivers?','["Rivers had no use", "Rivers provided water, transportation and fertile soil for farming", "Rivers blocked trade", "Rivers were mountains"]'::jsonb,1,'Physical geography shaped settlement patterns.','original'),
('113.50.c.6.C',3,'Land use issues during the Mexican Revolution included conflicts over what?','["The color of flags", "The cost of tickets", "Control of large estates held by a few wealthy landowners", "The color of maps"]'::jsonb,2,'Peasants demanded land reform.','original'),
('113.50.c.6.C',3,'Land grants from Spain and Mexico became central to disputes after the Mexican-American War because what?','["Everyone returned to Mexico", "Land became free", "Titles were erased by treaty", "Many Mexican landowners had to defend their ownership under U.S. law"]'::jsonb,3,'The treaty promised property protection that was often ignored.','original'),
('113.50.c.6.D',3,'Which factor pushed many Mexicans to migrate north between the 1910s and 1930s?','["The Mexican Revolution and economic hardship", "A new highway to Canada", "Nationwide peace", "Cheap airfare"]'::jsonb,0,'The Revolution displaced people.','original'),
('113.50.c.6.D',3,'Railroads in the early 1900s helped Mexican migration by doing what?','["Blocking travel", "Connecting Mexican towns with jobs in the U.S. Southwest", "Closing the border", "Ending trade"]'::jsonb,1,'Railroad work attracted laborers.','original'),
('113.50.c.6.E',3,'During the Bracero Program, many Mexican workers were employed in what?','["Banking", "Video game design", "Agricultural fields in the Southwest and beyond", "Space programs"]'::jsonb,2,'Farms needed workers during the war.','original'),
('113.50.c.6.E',3,'The Bracero Program ran from 1942 to which approximate year?','["1942", "1990", "1930", "1964"]'::jsonb,3,'It lasted over two decades.','original'),
('113.50.c.6.F',3,'Mexican American migration within the United States today includes movement to what?','["Growing metropolitan areas in states such as Texas, Georgia and the Midwest", "Only rural Mexico", "Only Alaska", "Only one state"]'::jsonb,0,'Migration patterns have diversified.','original'),
('113.50.c.6.F',3,'A factor in contemporary Mexican migration is what?','["Free tickets", "Economic opportunity and family connections", "A ban on travel", "A lack of borders"]'::jsonb,1,'Push and pull factors continue to shape migration.','original'),
('113.50.c.8.A',3,'Mexican Americans have participated in government by doing what?','["Avoiding politics", "Being barred from all offices", "Voting, running for office and organizing for change", "Having no voice"]'::jsonb,2,'Civic participation includes elections and advocacy.','original'),
('113.50.c.8.A',3,'Which action is an example of civic participation?','["Staying uninformed", "Ignoring local issues", "Avoiding elections", "Registering voters in a community"]'::jsonb,3,'Voter registration expands participation.','original'),
('113.50.c.8.B',3,'Delgado v. Bastrop ISD (1948) held that what was unlawful?','["Separating Mexican American students into segregated schools", "Paying teachers", "Building schools", "Teaching in Spanish"]'::jsonb,0,'It was part of the legal challenges to school segregation.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_mas_v1'
from (values
('113.50.c.8.B',3,'The biracial paradigm refers to a view that society is divided into what two groups?','["Young and old", "Black and white", "Rural and urban", "Rich and poor"]'::jsonb,1,'These cases showed that Mexican Americans were also affected by segregation.','original'),
('113.50.c.8.D',3,'A success of the Mexican American civil rights movement was what?','["Abolition of the Constitution", "The end of all discrimination", "Greater political representation and legal protections", "Open borders for all"]'::jsonb,2,'Gains were real but incomplete.','original'),
('113.50.c.8.D',3,'A continuing challenge the movement faced was what?','["Too many voters", "Too many schools", "Equal pay", "Unequal school funding and economic disparities"]'::jsonb,3,'Not all goals were achieved.','original'),
('113.50.c.8.E',3,'Plyler v. Doe (1982) ruled that states may not do what?','["Deny free public education to children because they are undocumented", "Require school attendance", "Fund schools", "Build classrooms"]'::jsonb,0,'The Court cited the Equal Protection Clause.','original'),
('113.50.c.8.E',3,'Miranda v. Arizona (1966) required police to do what?','["Skip trials", "Inform suspects of their rights before questioning", "Close courts", "Arrest without cause"]'::jsonb,1,'Ernesto Miranda, a Mexican American, was the defendant.','original'),
('113.50.c.8.F',3,'LULAC, founded in 1929, works to do what?','["Govern Texas", "Run the military", "Advance the civil rights and educational opportunities of Latinos", "Sell farm equipment"]'::jsonb,2,'It is one of the oldest Latino civil rights groups.','original'),
('113.50.c.8.F',3,'MALDEF is an organization that does what?','["Builds highways", "Trains pilots", "Regulates banks", "Uses the legal system to protect Latino civil rights"]'::jsonb,3,'It was founded in 1968.','original'),
('113.50.c.9.A',3,'Which is a responsibility of a U.S. citizen?','["Serving on a jury when called", "Ignoring laws", "Avoiding taxes", "Skipping all elections by law"]'::jsonb,0,'Citizens vote, pay taxes and serve on juries.','original'),
('113.50.c.9.A',3,'Immigrants living in the United States have which basic protection?','["No obligations", "Due process under the law", "Immunity from the law", "The right to vote in all elections"]'::jsonb,1,'Constitutional protections extend to persons within U.S. jurisdiction.','original'),
('113.50.c.9.B',3,'Cultural citizenship refers to what?','["A tax form", "A passport", "Belonging to a community through culture and participation, not only legal status", "A birth certificate"]'::jsonb,2,'Formal citizenship is legal membership.','original'),
('113.50.c.9.B',3,'Formal citizenship is defined by what?','["Food preferences", "Music taste", "Language only", "Legal membership in a nation, such as by birth or naturalization"]'::jsonb,3,'It is a legal status.','original'),
('113.50.c.9.C',3,'Individuals contribute to national identity when they do what?','["Share their cultural traditions, work and civic participation", "Hide their heritage", "Avoid community", "Reject all change"]'::jsonb,0,'Diversity shapes the nation.','original'),
('113.50.c.9.C',3,'The United States is sometimes described as a nation of what?','["No cultures", "Many cultures contributing to a shared identity", "One culture only", "Only recent arrivals"]'::jsonb,1,'Identity is shaped by many groups.','original'),
('113.50.c.9.D',3,'The term "Chicano" became widely used during the civil rights era to express what?','["A government label only", "A type of food", "Pride in Mexican American identity and political activism", "An old tax"]'::jsonb,2,'Many activists adopted it in the 1960s.','original'),
('113.50.c.9.D',3,'The term "Hispanic" is associated with what history?','["A Revolution slogan", "An Aztec title", "A Spanish law", "A broad label popularized for people with Spanish-speaking heritage, including in U.S. government use"]'::jsonb,3,'People use different terms for different reasons.','original'),
('113.50.c.10.A',3,'Mexican American history and issues have been reflected in art through what?','["Murals, music, film and literature", "Only statistics", "Only laws", "Only maps"]'::jsonb,0,'Artists respond to social issues.','original'),
('113.50.c.10.A',3,'Corridos are folk ballads that often do what?','["Give weather reports", "Tell stories about heroes, events and struggles", "Announce prices", "List recipes"]'::jsonb,1,'They are part of Mexican musical tradition.','original'),
('113.50.c.10.B',3,'"I am Joaquín" (1967) by Rodolfo "Corky" Gonzales is significant because it does what?','["Lists census numbers", "Explains tax law", "Expresses Mexican American identity and pride in an epic poem", "Describes a recipe"]'::jsonb,2,'It became a landmark of the Chicano movement.','original'),
('113.50.c.10.B',3,'Luis Valdez wrote "Pensamiento Serpentino" in 1971. He is also known for founding what?','["The G.I. Forum", "MALDEF", "The Border Patrol", "El Teatro Campesino"]'::jsonb,3,'His theater supported farmworkers.','original'),
('113.50.c.10.C',3,'El Teatro Campesino used short plays to do what?','["Inform and rally farmworkers during the strike", "Sell tickets for profit only", "Entertain royalty", "Teach calculus"]'::jsonb,0,'Actos made political points through performance.','original'),
('113.50.c.10.C',3,'Why is artistic expression effective in social movements?','["It prevents action", "It can inspire emotions and unite people around a cause", "It replaces law", "It hides messages"]'::jsonb,1,'Art mobilizes communities.','original'),
('113.50.c.10.D',3,'Sandra Cisneros is a Mexican American author known for what work?','["The Declaration of Independence", "The Texas Constitution", "The House on Mango Street", "I am Joaquín"]'::jsonb,2,'Her stories explore identity and community.','original'),
('113.50.c.10.D',3,'Norma Alarcón is a Chicana writer and editor who is known for what?','["Leading the UFW", "Founding LULAC", "Directing NASA", "Founding a press that publishes Chicana and Latina feminist writing"]'::jsonb,3,'She edited Third Woman Press.','original'),
('113.50.c.10.E ',3,'Tejano music, a Texas Mexican American tradition, blends what?','["Mexican folk music with polka and other regional styles", "Only opera", "Only drums", "Only jazz"]'::jsonb,0,'Selena became a star in the genre.','original'),
('113.50.c.10.E ',3,'Mexican American popular culture has influenced the world in areas such as what?','["Only tax law", "Food, music and film", "Only geology", "Only mathematics"]'::jsonb,1,'Tacos and mariachi are global.','original'),
('113.50.c.11.A',3,'The Maya are known for developing which mathematical idea?','["Calculus", "Logarithms", "The concept of zero", "The metric system"]'::jsonb,2,'They used a base-20 system.','original'),
('113.50.c.11.A',3,'The Aztec capital Tenochtitlan showed advanced engineering through what?','["Interstate highways", "Skyscrapers", "Railroads", "Causeways, canals and aqueducts"]'::jsonb,3,'These supported a large city on a lake.','original'),
('113.50.c.11.B',3,'Mario Molina earned a Nobel Prize in Chemistry for research on what?','["The ozone layer and chemicals that damage it", "Plant breeding", "Rocket fuel", "Gold mining"]'::jsonb,0,'He shared the 1995 prize.','original'),
('113.50.c.11.B',3,'Ellen Ochoa was the first Hispanic woman to do what?','["Become President", "Travel into space", "Win a Nobel Prize", "Climb Everest"]'::jsonb,1,'She flew on a Space Shuttle in 1993.','original'),
('113.50.c.12.A',3,'Using the term "naturalization" correctly means referring to what?','["A type of farming", "A kind of tax", "The legal process of becoming a citizen", "A map projection"]'::jsonb,2,'Terminology must be used precisely.','original'),
('113.50.c.12.A',3,'Which term describes a person who moves permanently to another country?','["Juror", "Delegate", "Voter", "Immigrant"]'::jsonb,3,'Accurate terms avoid confusion.','original'),
('113.50.c.12.B',3,'To analyze diverse points of view on a contemporary issue, a student should do what?','["Read perspectives from people with different experiences", "Rely on rumors", "Skip evidence", "Use one source"]'::jsonb,0,'Multiple perspectives give a fuller picture.','original'),
('113.50.c.12.B',3,'Two groups disagree about immigration policy. This shows what?','["Policy never changes", "Different values and experiences can lead to different viewpoints", "Facts do not matter", "One group is always lying"]'::jsonb,1,'Analyze reasons behind positions.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_mas_v1'
from (values
('113.50.c.12.C ',3,'A strong presentation on a contemporary issue includes what?','["No sources", "Rumors", "A clear thesis supported by credible sources", "Only opinions"]'::jsonb,2,'Critical inquiry strengthens the product.','original'),
('113.50.c.12.C ',3,'Critical methods of inquiry begin with what?','["A rumor", "A slogan", "A guess", "A focused question and reliable evidence"]'::jsonb,3,'Research is question driven.','original'),
('113.50.c.12.D ',3,'Identifying how the Mexican Revolution led to increased migration north is what skill?','["Finding cause-and-effect relationships", "Memorizing dates", "Reading a legend", "Copying text"]'::jsonb,0,'It connects events and outcomes.','original'),
('113.50.c.12.D ',3,'Drawing a conclusion from a set of census data is what skill?','["Rewriting facts", "Making inferences and conclusions from evidence", "Guessing", "Ignoring data"]'::jsonb,1,'Conclusions must follow the data.','original'),
('113.50.c.7.A',3,'Mexican repatriation in the 1930s resulted in what?','["The creation of the Bracero Program", "A new treaty", "Hundreds of thousands of people of Mexican descent, including U.S. citizens, leaving the United States", "Higher wages for all"]'::jsonb,2,'It occurred during the Great Depression.','original'),
('113.50.c.7.A',3,'Repatriation affected the economy by doing what?','["Raising wages for farmworkers", "Ending the Depression", "Creating more jobs for everyone", "Removing workers and consumers from communities and businesses"]'::jsonb,3,'Communities lost labor and customers.','original'),
('113.50.c.7.B',3,'The Bracero Program helped the war effort by doing what?','["Supplying agricultural labor while many U.S. workers served in the military", "Creating schools", "Writing laws", "Building ships"]'::jsonb,0,'Farm output supported the nation.','original'),
('113.50.c.7.B',3,'Braceros often faced which problem?','["Free housing in every case", "Low wages and poor working and living conditions", "No work at all", "High salaries"]'::jsonb,1,'Abuses led to criticism of the program.','original'),
('113.50.c.7.C',3,'The farmworkers union struggle sought to win what?','["Larger farms", "New roads", "Better wages, safer conditions and the right to organize", "Lower taxes"]'::jsonb,2,'The UFW used strikes and boycotts.','original'),
('113.50.c.7.C',3,'The Delano grape strike of 1965 was significant because it did what?','["Ended the Bracero Program", "Created the Border Patrol", "Started the Revolution", "Drew national attention to farmworker conditions"]'::jsonb,3,'Filipino and Mexican American workers joined together.','original'),
('113.50.c.7.D',3,'Mexican American workers contribute to the U.S. economy in sectors such as what?','["Agriculture, construction, services and professional fields", "Only the military", "Only fishing", "Only mining"]'::jsonb,0,'They work across the economy.','original'),
('113.50.c.7.D',3,'Small businesses owned by Mexican Americans contribute to the economy by doing what?','["Reducing wages for all", "Creating jobs and generating tax revenue", "Ending trade", "Eliminating competition"]'::jsonb,1,'Entrepreneurship grows communities.','original'),
('113.50.c.7.E',3,'Purchasing power refers to what?','["The size of a house", "The number of banks", "The amount of goods and services a group can buy with its income", "A tax rate"]'::jsonb,2,'It influences consumer markets and GDP.','original'),
('113.50.c.7.E',3,'The growing Mexican American population affects GDP by doing what?','["Removing taxes", "Ending trade", "Reducing demand", "Increasing consumer spending on goods and services"]'::jsonb,3,'Consumption is a main part of GDP.','original'),
('113.50.c.7.F ',3,'Which is a current issue related to the Mexican American labor force?','["Wage fairness and immigration policy", "Space travel", "Ancient trade", "Typewriters"]'::jsonb,0,'Policy debates affect workers.','original'),
('113.50.c.7.F ',3,'Workers'' access to fair pay and safe conditions is affected by what?','["The weather", "Labor laws and their enforcement", "Sports schedules", "Time zones"]'::jsonb,1,'Enforcement matters for protection.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
